pub fn changed_paths_under(
    repo: &Path,
    git_ref: &str,
    prefix: &str,
) -> Result<Vec<String>, WorkingTreeDiffError> {
    let prefix_path = Path::new(prefix);
    if prefix.is_empty()
        || prefix.len() > MAX_GIT_PATHSPEC_BYTES
        || prefix.contains('\0')
        || prefix_path.is_absolute()
        || prefix_path
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return Err(WorkingTreeDiffError::SnapshotChanged);
    }
    let deadline = Some(Instant::now() + git_timeout());
    let baseline_oid = resolve_commit_controlled(repo, git_ref, deadline, None)?;
    let head_oid = resolve_head_controlled(repo, deadline, None)?;
    let literal_pathspec = format!(":(top,literal){prefix}");
    let output = run_bounded_git_controlled(
        repo,
        &[
            "-c",
            "diff.external=",
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--no-renames",
            "--name-only",
            "-z",
            &baseline_oid,
            &head_oid,
            "--",
            &literal_pathspec,
        ],
        None,
        GIT_OUTPUT_LIMIT,
        deadline,
        None,
    )?;
    if !output.success {
        return Err(WorkingTreeDiffError::InvalidRef);
    }
    let mut paths = BTreeSet::new();
    for raw in nul_fields(&output.stdout) {
        let path = std::str::from_utf8(raw)
            .map_err(|_| WorkingTreeDiffError::SnapshotChanged)?
            .to_string();
        let parsed = Path::new(&path);
        if parsed.is_absolute()
            || parsed
                .components()
                .any(|component| !matches!(component, std::path::Component::Normal(_)))
            || !parsed.starts_with(prefix_path)
        {
            return Err(WorkingTreeDiffError::SnapshotChanged);
        }
        paths.insert(path);
    }
    Ok(paths.into_iter().collect())
}

fn parse_lcov(
    root: &Path,
    relevant: &BTreeSet<String>,
    bytes: &[u8],
    deadline: Option<Instant>,
) -> Result<(CoverageRecords, SourceStats), SourceFailure> {
    let text = std::str::from_utf8(bytes).map_err(|_| SourceFailure::InvalidUtf8)?;
    let mut records = CoverageRecords::new();
    let mut current = None;
    let mut stats = SourceStats::default();
    let mut saw_format_marker = false;
    for (line_index, line) in text.lines().enumerate() {
        if line_index.is_multiple_of(4_096) && deadline.is_some_and(|value| Instant::now() >= value)
        {
            stats.partial = true;
            stats.deadline_reached = true;
            break;
        }
        if let Some(path) = line.strip_prefix("SF:") {
            saw_format_marker = true;
            current = match normalize_evidence_path(root, path.trim(), relevant) {
                Ok(path) => path,
                Err(_) => {
                    stats.partial = true;
                    stats.invalid_records = true;
                    None
                }
            };
            continue;
        }
        if line == "end_of_record" {
            saw_format_marker = true;
            current = None;
            continue;
        }
        let Some(data) = line.strip_prefix("DA:") else {
            saw_format_marker |= line.starts_with("TN:");
            continue;
        };
        saw_format_marker = true;
        if stats.facts_total >= MAX_SOURCE_FACTS {
            stats.partial = true;
            stats.work_limited = true;
            break;
        }
        stats.facts_total += 1;
        let mut fields = data.split(',');
        let Some(line_number) = fields.next().and_then(|value| value.parse::<u32>().ok()) else {
            stats.partial = true;
            stats.invalid_records = true;
            continue;
        };
        let Some(hits) = fields.next().and_then(|value| value.parse::<u64>().ok()) else {
            stats.partial = true;
            stats.invalid_records = true;
            continue;
        };
        if let Some(path) = &current {
            records
                .entry(path.clone())
                .or_default()
                .entry(line_number)
                .and_modify(|value| *value = (*value).max(hits))
                .or_insert(hits);
        }
    }
    if !saw_format_marker {
        return Err(SourceFailure::InvalidFormat);
    }
    Ok((records, stats))
}

fn load_coverage(&mut self, path: &Path, id: String) {
    let fallback = requested_label(path);
    let input = match self.read_source(path) {
        Ok(input) => input,
        Err(error) => return self.source_error(id, "coverage", fallback, error),
    };
    self.register_artifact(&id, &input);
    let label = input.label;
    let coverage_bytes = strip_utf8_bom(&input.bytes);
    let first = coverage_bytes
        .iter()
        .copied()
        .find(|byte| !byte.is_ascii_whitespace());
    let result = if first == Some(b'<') {
        parse_cobertura(self.root, &self.relevant, coverage_bytes, self.deadline)
    } else {
        parse_lcov(self.root, &self.relevant, coverage_bytes, self.deadline)
    };
    let (records, mut stats) = match result {
        Ok(value) => value,
        Err(error) => return self.source_error(id, "coverage", label, error),
    };
    'records: for (repo_path, lines) in records {
        for (line, hits) in lines {
            if self.deadline_reached() {
                stats.partial = true;
                stats.deadline_reached = true;
                break 'records;
            }
            if self.add_coverage(&repo_path, &id, line, hits) {
                stats.facts_returned += 1;
                stats.files.insert(repo_path.clone());
            } else {
                stats.partial = true;
                stats.work_limited = true;
            }
        }

pub(crate) fn collection_sources(
    &self,
    project_root: &str,
    after: &str,
    limit: usize,
    include_excluded: bool,
) -> SqlResult<Vec<CollectionSourceSelection>> {
    if !self.has_table("persona_collection_source")? {
        return Ok(Vec::new());
    }
    let enabled = if self.has_table("persona_sync_exclusion")? {
        "NOT EXISTS(SELECT 1 FROM persona_sync_exclusion x WHERE x.source=s.source)"
    } else {
        "1"
    };
    let mut stmt = self.conn.prepare(&format!(
        "SELECT source, source_path, project_root, project, repository, snapshot_digest,
                extractor, bytes, lines, {enabled} FROM persona_collection_source s
         WHERE project_root = ?1 AND source > ?2 AND (?4 OR ({enabled}))
         ORDER BY source LIMIT ?3"
    ))?;
    let rows = stmt.query_map(
        params![project_root, after, limit as i64, include_excluded],
        |row| {
            Ok(CollectionSourceSelection {
                snapshot: source_row(row)?,
                sync_enabled: row.get(9)?,
            })
        },
    )?;
    rows.collect()
}

/// Changes only future sync selection; retained evidence and explicit
/// collection are independent. A collect never removes this exclusion.
pub(crate) fn set_source_sync_enabled(
    &mut self,
    source: &str,
    project_root: &str,
    enabled: bool,
) -> SqlResult<()> {
    let tx = self
        .conn
        .transaction_with_behavior(TransactionBehavior::Immediate)?;
    let matches = tx
        .prepare("SELECT 1 FROM persona_collection_source WHERE source=?1 AND project_root=?2")?
        .exists(params![source, project_root])?;
    if !matches {
        return Err(rusqlite::Error::InvalidParameterName(
            "source is not registered for this project root".into(),
        ));
    }
    if enabled {
        tx.execute(
            "DELETE FROM persona_sync_exclusion WHERE source=?1",
            [source],
        )?;
    } else {
        tx.execute("INSERT OR IGNORE INTO persona_sync_exclusion(source,excluded_at) VALUES(?1,unixepoch())", [source])?;
    }
    check_size(&tx)?;
    tx.commit()
}

fn prepare_page(
    db: Option<&ProfileStore>,
    root: &Path,
    after: Option<&str>,
    limit: usize,
) -> Result<(SourcePage, Vec<CollectionBatch>), Box<dyn std::error::Error>> {
    let page = page(db, root, after, limit, false)?;
    let inputs: Vec<_> = page
        .sources
        .iter()
        .map(|source| CollectionInput::Registered(&source.snapshot))
        .collect();
    let batches = if inputs.is_empty() {
