class Root:
    def __init__(self, path: Path):
        if os.name != "posix" or not hasattr(os, "O_NOFOLLOW"):
            raise artifact_io.BenchmarkError("review_platform", "review artifacts require POSIX no-follow directory operations")
        self.path = path.absolute()
        if self.path != self.path.resolve(strict=True):
            raise artifact_io.BenchmarkError("review_path", "artifact directory must be canonical, without symbolic links")
        self.fd = os.open(self.path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)

@contextmanager
def parent(self, path, create=False):
    parts = relative(path)
    descriptors = [os.dup(self.fd)]
    try:
        for part in parts[:-1]:
            if create:
                try:
                    os.mkdir(part, 0o700, dir_fd=descriptors[-1])
                except FileExistsError:
                    pass
            descriptors.append(os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                                       dir_fd=descriptors[-1]))
        yield descriptors[-1], parts[-1]
    finally:
        for fd in reversed(descriptors):
            os.close(fd)

def read(self, path, limit=artifact_io.CONTROL_BYTE_LIMIT, optional=False):
    try:
        with self.parent(path) as (parent, name):
            expected_parent = os.fstat(parent)
            fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=parent)
            with os.fdopen(fd, "rb") as stream:
                before = os.fstat(stream.fileno())
                if not stat.S_ISREG(before.st_mode) or before.st_size > limit:
                    raise artifact_io.BenchmarkError("review_file", "artifact must be a bounded regular file")
                body = stream.read(limit + 1)
                after = os.fstat(stream.fileno())
            current = os.stat(name, dir_fd=parent, follow_symlinks=False)
            if len(body) > limit or identity(before) != identity(after) or identity(after) != identity(current):
                raise artifact_io.BenchmarkError("review_changed", "artifact changed while reading")
            self.check_parent(path, expected_parent)
        self.read_bytes += len(body)
        if self.read_bytes > READ_LIMIT:
            raise artifact_io.BenchmarkError("review_limit", "review input exceeds its aggregate read cap")
        self.check_root()
        self.records[path] = {"sha256": sha(body), "limit": limit, "identity": identity(before)}
        return body
    except FileNotFoundError:
        if not optional:
            raise artifact_io.BenchmarkError("review_missing", f"required artifact is absent: {path}")
        self.records[path] = {"sha256": None, "limit": limit, "identity": None}
        return None
    except OSError as error:
        raise artifact_io.BenchmarkError("review_path", f"cannot read artifact without following links: {path}") from error

